mapper.select:
select cb.*,c.name as categoryName,b.name as brandName,b.logo from category_brand cb inner join category c on cb.category_id = c.id inner join brand b on cb.brand_id = b.id
and cb.brand_id = #{categoryBrandDto.brandId}
and cb.category_id = #{categoryBrandDto.categoryId}
and cb.is_deleted = 0
order by cb.id desc
